steps.detail:
{
  "bodies": *[_type == "body" && (name match "T5i" || aliases[] match "T5i" || name match "700D" || aliases[] match "700D")]{_id, name, aliases, "mountId": mount._ref, liveViewAf, videoContinuousAf},
  "lenses": *[_type == "lens" && ((name match "18-55" && name match "STM") || aliases[] match "18-55" || aliases[] match "STM")]{_id, name, aliases, "mountId": mount._ref, focusMotor}
}

{
 "compat": *[_type == "compatibilityRecord"
   && (!defined(bodies) || count(bodies) == 0 || "body-canon-t5i" in bodies[]._ref)
   && ("lens-canon-efs-18-55-is-stm" in lenses[]._ref || lensMount._ref == "mount-canon-ef-s" || focusMotor == "stm")
   && (!defined(adapters) || count(adapters) == 0)
 ]{_id, shootingMode, singleAf, continuousAf, dmf, behaviour, bodyCondition, note, source},
 "caveats": *[_type == "focusCaveat"
   && (!defined(bodies) || count(bodies) == 0 || "body-canon-t5i" in bodies[]._ref)
   && (!defined(lenses) || count(lenses) == 0 || "lens-canon-efs-18-55-is-stm" in lenses[]._ref)
 ]{_id, title, shootingMode, appliesWhen, effect, remedy, source}
}

{
  "bodies": *[_type == "body" && (name match "a7 IV" || aliases[] match "a7 IV" || name match "α7 IV" || aliases[] match "α7 IV")]{_id, name, aliases, "mountId": mount._ref},
  "lenses": *[_type == "lens" && (name match "Sigma 35mm F1.4" || aliases[] match "Sigma 35mm F1.4" || name match "35mm F1.4 Art" || aliases[] match "35mm F1.4 Art" || name match "35mm F1.4 DG HSM" || aliases[] match "35mm F1.4 DG HSM")]{_id, name, aliases, focusMotor, "mountId": mount._ref},
  "adapters": *[_type == "adapter" && (name match "MC-11" || aliases[] match "MC-11")]{_id, name, maker, "lensMountId": lensMount._ref, "bodyMountId": bodyMount._ref}
}

{
  "compat": *[_type == "compatibilityRecord"
    && (!defined(bodies) || count(bodies) == 0 || "body-sony-a7iv" in bodies[]._ref)
    && ("lens-sigma-art-35mm-f1-4-dg-hsm" in lenses[]._ref || focusMotor == "hsm")
    && ("adapter-sigma-mc11-ef-e" in adapters[]._ref || "adapter-sigma-mc11-sa-e" in adapters[]._ref)
  ]{_id, shootingMode, singleAf, continuousAf, dmf, behaviour, bodyCondition, note, "lenses": lenses[]->{_id,name}, "adapters": adapters[]->{_id,name}, source},
  "caveats": *[_type == "focusCaveat"
    && (!defined(bodies) || count(bodies) == 0 || "body-sony-a7iv" in bodies[]._ref)
    && (!defined(lenses) || count(lenses) == 0 || "lens-sigma-art-35mm-f1-4-dg-hsm" in lenses[]._ref)
    && (@ match text::query("MC-11") || title match text::query("MC-11") || appliesWhen match text::query("MC-11"))
  ]{_id, title, shootingMode, appliesWhen, effect, remedy, "bodies": bodies[]->{_id,name}, "lenses": lenses[]->{_id,name}, source}
}

{
  "bodiesSony": *[_type == "body" && (name match text::query("Sony") || maker match "Sony")]{_id, name, aliases, "mount": mount->name}[0...50],
  "lenses": *[_type == "lens" && (name match text::query("Canon EF 50mm f/1.8 II") || aliases[] match text::query("Canon EF 50mm f/1.8 II") || name match text::query("50mm 1.8 II") || aliases[] match text::query("50mm 1.8 II"))]{_id, name, aliases, focusMotor, "mountId": mount._ref, "mount": mount->name},
  "adapters": *[_type == "adapter" && (name match text::query("Metabones Mark V") || aliases[] match text::query("Metabones Mark V") || name match text::query("Metabones") || aliases[] match text::query("Metabones"))]{_id, name, maker, "lensMountId": lensMount._ref, "lensMount": lensMount->name, "bodyMount": bodyMount->name}
}

{
  "compat": *[_type == "compatibilityRecord"
    && ("lens-canon-ef-50-f18-ii" in lenses[]._ref || lensMount._ref == "mount-canon-ef" || focusMotor == "microMotor")
    && "adapter-metabones-ef-e-t-mkv" in adapters[]._ref
  ]{_id, scope, shootingMode, singleAf, continuousAf, dmf, behaviour, bodyCondition, note, source, "bodies": bodies[]->{_id,name}, "lenses": lenses[]->{_id,name}, "lensMount": lensMount->name, focusMotor, "adapters": adapters[]->{_id,name}},
  "caveats": *[_type == "focusCaveat"
    && ((!defined(lenses) || count(lenses)==0 || "lens-canon-ef-50-f18-ii" in lenses[]._ref)
        || title match text::query("Metabones Canon EF 50 1.8") || appliesWhen match text::query("Metabones Canon EF 50 1.8"))
  ]{_id, title, shootingMode, appliesWhen, effect, remedy, source, "bodies": bodies[]->{_id,name}, "lenses": lenses[]->{_id,name}}
}

{
  "bodies": *[_type == "body" && (name match "Canon EOS R6" || aliases[] match "Canon EOS R6" || name match "EOS R6" || aliases[] match "EOS R6")]{_id, name, aliases, "mountId": mount->_id, "mountName": mount->name},
  "lenses": *[_type == "lens" && (name match "Nikon AF-S 50mm f/1.8G" || aliases[] match "Nikon AF-S 50mm f/1.8G" || name match "AF-S 50mm" || aliases[] match "AF-S 50mm" || name match "50mm f/1.8G" || aliases[] match "50mm f/1.8G")]{_id, name, aliases, focusMotor, "mountId": mount->_id, "mountName": mount->name},
  "adapters": *[_type == "adapter" && (name match "F-to-RF" || aliases[] match "F-to-RF" || name match "Nikon F Canon RF" || name match "F RF" || name match "F to RF")]{_id, name, maker, electronic, "lensMountId": lensMount->_id, "lensMountName": lensMount->name, "bodyMountId": bodyMount->_id, "bodyMountName": bodyMount->name}
}

{
  "bodies": *[_type == "body" && (name match "R6" || aliases[] match "R6" || name match "Canon" || aliases[] match "Canon")]{_id, name, aliases, "mountId": mount->_id, "mountName": mount->name}[0...20],
  "lenses": *[_type == "lens" && (name match "Nikon" || aliases[] match "Nikon" || name match "50mm" || aliases[] match "50mm" || name match "AF-S" || aliases[] match "AF-S")]{_id, name, aliases, focusMotor, "mountId": mount->_id, "mountName": mount->name}[0...30],
  "adapters": *[_type == "adapter"]{_id, name, maker, electronic, "lensMountId": lensMount->_id, "lensMountName": lensMount->name, "bodyMountId": bodyMount->_id, "bodyMountName": bodyMount->name}
}

{
  "mounts": *[_type == "mount" && (name match "Nikon" || name match "F" || name match "RF" || name match "Canon RF")]{_id, name, maker, system},
  "compatCandidates": *[_type == "compatibilityRecord" && (@ match text::query("Nikon F RF EOS R6 AF-S 50mm"))]{_id, shootingMode, singleAf, continuousAf, "lenses": lenses[]->name, "lensMount": lensMount->name, focusMotor, "bodies": bodies[]->name, "adapters": adapters[]->name, source}[0...10],
  "caveatCandidates": *[_type == "focusCaveat" && (@ match text::query("Nikon F RF EOS R6 AF-S 50mm"))]{_id, title, appliesWhen, shootingMode, effect, remedy, "bodies": bodies[]->name, "lenses": lenses[]->name, source}[0...10]
}
